31	// EventInput carries the validated fields an append needs. Seq is nil when the
32	// caller lets the service assign the next sequence number.
33	type EventInput struct {
34		Seq        *int64
35		Account    string
36		Operation  string
37		Resource   string
38		Result     string
39		OccurredAt string
40	}
