12	func getEventsQuery(t *testing.T, router http.Handler, rawQuery string) *httptest.ResponseRecorder {
13		t.Helper()
14		recorder := httptest.NewRecorder()
15		target := "/events"
16		if rawQuery != "" {
17			target += "?" + rawQuery
18		}
19		request := httptest.NewRequest(http.MethodGet, target, nil)
20		router.ServeHTTP(recorder, request)
21		return recorder
22	}
23	
24	// mustPost appends one event and returns the decoded 201 body.
25	func mustPost(t *testing.T, router http.Handler, body string) map[string]any {
26		t.Helper()
27		recorder := postEventBody(t, router, body)
28		if recorder.Code != http.StatusCreated {
29			t.Fatalf("seed post: status = %d (%s)", recorder.Code, recorder.Body.String())
30		}
31		return decodeEvent(t, recorder)
32	}
33	
34	// eventBody builds a valid append body for the given account and occurred_at.
35	func eventBody(account, occurredAt string) string {
36		return fmt.Sprintf(`{"account":%q,"operation":"op","resource":"res","result":"ok","occurred_at":%q}`, account, occurredAt)
37	}
38	
39	// decodePage decodes a 200 GET /events body and checks the top-level shape:
40	// exactly the events and next_after_seq keys.
41	func decodePage(t *testing.T, recorder *httptest.ResponseRecorder) (events []map[string]any, next any) {
42		t.Helper()
43		var decoded map[string]any
44		if err := json.Unmarshal(recorder.Body.Bytes(), &decoded); err != nil {
45			t.Fatalf("decode page: %v", err)
46		}
47		if len(decoded) != 2 {
48			t.Fatalf("response keys = %v, want only events and next_after_seq", decoded)
49		}
50		rawEvents, ok := decoded["events"].([]any)
51		if !ok {
52			t.Fatalf("events = %v, want an array", decoded["events"])
53		}
54		for _, raw := range rawEvents {
55			event, ok := raw.(map[string]any)
56			if !ok {
57				t.Fatalf("event = %v, want an object", raw)
58			}
59			events = append(events, event)
60		}
61		return events, decoded["next_after_seq"]
62	}
63	
64	// wantSeqs asserts the page carries exactly the given seq values in order.
65	func wantSeqs(t *testing.T, events []map[string]any, seqs ...float64) {
66		t.Helper()
67		if len(events) != len(seqs) {
68			t.Fatalf("page has %d events, want %d (%v)", len(events), len(seqs), events)
69		}
70		for i, seq := range seqs {
71			if events[i]["seq"] != seq {
72				t.Fatalf("event %d seq = %v, want %v", i, events[i]["seq"], seq)
73			}
74		}
75	}
