1	package api
2	
3	// Regression tests for read failures that strike mid-scan while the database
4	// itself stays reachable (unlike the closed-handle cases, which fail before
5	// the first row):
6	//
7	//   - GET /events and GET /ledger/verify read a valid record prefix, then hit
8	//     a storage error on a later row; both answer 503 storage_unavailable
9	//     with a bare top-level error object and no partial result fields;
10	//   - invalid input (limit=0, verify query parameters) still wins a 400
11	//     invalid_audit_input over the storage failure, in the same body shape;
12	//   - GET /healthz keeps reporting ok throughout the read fault;
13	//   - a broken back-link at seq 2 stops verification there even when a read
14	//     fault waits at seq 3;
15	//   - once the ledger and the read path are restored, pagination returns the
16	//     original records ending in a null cursor, verification reports a valid
17	//     full chain, and appends still chain onto the original tail.
18	//
19	// The fault is injected by renaming the events table and putting a view in
20	// its place that serves rows below a cutoff and raises an error when the scan
21	// reaches it, so the database stays open and healthy the whole time.
22	
23	import (
24		"database/sql"
25		"encoding/json"
26		"fmt"
27		"net/http"
28		"net/http/httptest"
29		"path/filepath"
30		"reflect"
31		"strings"
32		"testing"
33	)
34	
35	// failReadsAt swaps the events table for a view that serves rows with seq
36	// below failAt unchanged and raises a storage error when the scan reaches
37	// failAt. The database stays open and answers pings.
38	func failReadsAt(t *testing.T, path string, failAt int64) {
39		t.Helper()
40		corrupt(t, path, "ALTER TABLE events RENAME TO events_data")
41		corrupt(t, path, fmt.Sprintf(
42			"CREATE VIEW events AS SELECT seq, account, operation, resource, result, occurred_at, prev_hash, "+
43				"CASE WHEN seq >= %d THEN json('[') ELSE hash END AS hash FROM events_data", failAt))
44	}
45	
46	// restoreReads undoes failReadsAt, putting the real table back in place.
47	func restoreReads(t *testing.T, path string) {
48		t.Helper()
49		corrupt(t, path, "DROP VIEW events")
50		corrupt(t, path, "ALTER TABLE events_data RENAME TO events")
51	}
52	
53	// assertFaultReadsPrefix confirms through an independent connection that the
54	// injected fault really serves exactly the wantSeqs prefix before the read
55	// fails, so the 503s above exercise a mid-scan failure, not an early one.
56	func assertFaultReadsPrefix(t *testing.T, path string, wantSeqs ...int64) {
57		t.Helper()
58		db, err := sql.Open("sqlite", path)
59		if err != nil {
60			t.Fatalf("open control connection: %v", err)
61		}
62		defer db.Close()
63	
64		// Select the hash column too: the fault lives in its CASE expression, so
65		// a seq-only scan would never evaluate it.
66		rows, err := db.Query("SELECT seq, hash FROM events ORDER BY seq ASC")
67		if err != nil {
68			t.Fatalf("query through fault view: %v", err)
69		}
70		var got []int64
71		for rows.Next() {
72			var seq int64
73			var hash string
74			if err := rows.Scan(&seq, &hash); err != nil {
75				t.Fatalf("scan through fault view: %v", err)
76			}
77			got = append(got, seq)
78		}
79		iterErr := rows.Err()
80		rows.Close()
81		if iterErr == nil {
82			t.Fatalf("fault view returned all rows without an error; want a failure after %v", wantSeqs)
83		}
84		if !reflect.DeepEqual(got, wantSeqs) {
85			t.Fatalf("fault view served seqs %v before failing, want %v", got, wantSeqs)
86		}
87	}
88	
89	// seedEvents appends n valid records and returns their 201 response bodies.
90	func seedEvents(t *testing.T, router http.Handler, n int) []map[string]any {
91		t.Helper()
92		posted := make([]map[string]any, 0, n)
93		for i := 0; i < n; i++ {
94			posted = append(posted, mustPost(t, router, eventBody("audit", fmt.Sprintf("2026-10-05T00:0%d:00Z", i))))
95		}
96		return posted
97	}
98	
99	// wantEventsMatchPosted fails unless every read-back record carries the same
100	// business fields, seq and chain values as its append response.
101	func wantEventsMatchPosted(t *testing.T, events, posted []map[string]any) {
102		t.Helper()
103		if len(events) != len(posted) {
104			t.Fatalf("read back %d events, want %d (%v)", len(events), len(posted), events)
105		}
106		for i := range posted {
107			for _, key := range []string{"account", "operation", "resource", "result", "occurred_at", "seq", "prev_hash", "hash"} {
108				if events[i][key] != posted[i][key] {
109					t.Fatalf("event %d %s = %v, want %v", i, key, events[i][key], posted[i][key])
110				}
111			}
112		}
113	}
114	
115	// wantStorageError asserts the 503 storage_unavailable shape: a single
116	// top-level error object with a non-empty message, none of the endpoint's
117	// partial result keys, and no SQL, stack or path leakage.
118	func wantStorageError(t *testing.T, recorder *httptest.ResponseRecorder, forbiddenKeys ...string) {
119		t.Helper()
120		if recorder.Code != http.StatusServiceUnavailable {
121			t.Fatalf("status = %d, want 503 (%s)", recorder.Code, recorder.Body.String())
122		}
123		var raw map[string]json.RawMessage
124		if err := json.Unmarshal(recorder.Body.Bytes(), &raw); err != nil {
125			t.Fatalf("decode error body: %v (%s)", err, recorder.Body.String())
126		}
127		if len(raw) != 1 {
128			t.Fatalf("top-level keys = %v, want only the error object", raw)
129		}
130		var decoded struct {
131			Error struct {
132				Code    string `json:"code"`
133				Message string `json:"message"`
134			} `json:"error"`
135		}
136		if err := json.Unmarshal(recorder.Body.Bytes(), &decoded); err != nil {
137			t.Fatalf("decode error body: %v (%s)", err, recorder.Body.String())
138		}
139		if decoded.Error.Code != "storage_unavailable" {
140			t.Fatalf("code = %q, want storage_unavailable", decoded.Error.Code)
141		}
142		if decoded.Error.Message == "" {
143			t.Fatal("message must be a non-empty string")
144		}
145		body := recorder.Body.String()
146		for _, key := range forbiddenKeys {
147			if strings.Contains(body, key) {
148				t.Fatalf("503 body carries partial result key %q: %s", key, body)
149			}
150		}
151		for _, leak := range []string{"SELECT", "sql", ".go", "goroutine", "/", "\\"} {
152			if strings.Contains(body, leak) {
153				t.Fatalf("error body leaks %q: %s", leak, body)
154			}
155		}
156	}
157	
158	// wantInvalidAuditInput asserts the 400 invalid_audit_input shape: a single
159	// top-level error object with a non-empty message.
160	func wantInvalidAuditInput(t *testing.T, recorder *httptest.ResponseRecorder) {
161		t.Helper()
162		if recorder.Code != http.StatusBadRequest {
163			t.Fatalf("status = %d, want 400 (%s)", recorder.Code, recorder.Body.String())
164		}
165		var raw map[string]json.RawMessage
166		if err := json.Unmarshal(recorder.Body.Bytes(), &raw); err != nil {
167			t.Fatalf("decode error body: %v (%s)", err, recorder.Body.String())
168		}
169		if len(raw) != 1 {
170			t.Fatalf("top-level keys = %v, want only the error object", raw)
171		}
172		var decoded struct {
173			Error struct {
174				Code    string `json:"code"`
175				Message string `json:"message"`
176			} `json:"error"`
177		}
178		if err := json.Unmarshal(recorder.Body.Bytes(), &decoded); err != nil {
179			t.Fatalf("decode error body: %v (%s)", err, recorder.Body.String())
180		}
181		if decoded.Error.Code != "invalid_audit_input" {
182			t.Fatalf("code = %q, want invalid_audit_input", decoded.Error.Code)
183		}
184		if decoded.Error.Message == "" {
185			t.Fatal("message must be a non-empty string")
186		}
187	}
