189	// wantHealthy asserts GET /healthz keeps its normal ok response.
190	func wantHealthy(t *testing.T, router http.Handler) {
191		t.Helper()
192		recorder := httptest.NewRecorder()
193		router.ServeHTTP(recorder, httptest.NewRequest(http.MethodGet, "/healthz", nil))
194		if recorder.Code != http.StatusOK || recorder.Body.String() != `{"database":"ok","status":"ok"}` {
195			t.Fatalf("healthz = %d %s, want the normal ok body", recorder.Code, recorder.Body.String())
196		}
197	}
