199	func TestGetEventsReadFailureAfterPrefixReturns503(t *testing.T) {
200		path := filepath.Join(t.TempDir(), "service.db")
201		st := openStoreAt(t, path)
202		defer closeStore(t, st)
203		router := NewRouter(st)
204		posted := seedEvents(t, router, 4)
205	
206		// Baseline: the intact ledger pages through all four records, and the
207		// read-back fields match the append responses.
208		page, next := decodePage(t, getEventsQuery(t, router, "limit=2"))
209		wantSeqs(t, page, 1, 2)
210		if next != float64(2) {
211			t.Fatalf("next_after_seq = %v, want 2", next)
212		}
213		second, next := decodePage(t, getEventsQuery(t, router, "limit=2&after_seq=2"))
214		wantSeqs(t, second, 3, 4)
215		if next != nil {
216			t.Fatalf("next_after_seq = %v, want null on the last page", next)
217		}
218		wantEventsMatchPosted(t, append(page, second...), posted)
219	
220		// Reads fail at seq 3 after serving the valid prefix; the database stays
221		// up. With limit=2 the request must still read seq 3 to size the page.
222		failReadsAt(t, path, 3)
223		assertFaultReadsPrefix(t, path, 1, 2)
224	
225		recorder := getEventsQuery(t, router, "limit=2")
226		wantStorageError(t, recorder, "events", "next_after_seq")
227	
228		// Only the read path is broken: healthz still reports ok.
229		wantHealthy(t, router)
230	
231		// Invalid input is still a 400 before storage is touched, in the same
232		// error body shape.
233		wantInvalidAuditInput(t, getEventsQuery(t, router, "limit=0"))
234	
235		// With the read path restored, pagination returns every original record
236		// again and the last page closes the cursor.
237		restoreReads(t, path)
238		page, next = decodePage(t, getEventsQuery(t, router, "limit=2"))
239		wantSeqs(t, page, 1, 2)
240		if next != float64(2) {
241			t.Fatalf("next_after_seq = %v, want 2", next)
242		}
243		second, next = decodePage(t, getEventsQuery(t, router, "limit=2&after_seq=2"))
244		wantSeqs(t, second, 3, 4)
245		if next != nil {
246			t.Fatalf("next_after_seq = %v, want null on the last page", next)
247		}
248		wantEventsMatchPosted(t, append(page, second...), posted)
249	
250		// Appends still chain onto the original tail.
251		fifth := mustPost(t, router, eventBody("audit", "2026-10-05T00:04:00Z"))
252		if fifth["seq"] != float64(5) || fifth["prev_hash"] != posted[3]["hash"] {
253			t.Fatalf("fifth = %v, want seq 5 chained to %s", fifth, posted[3]["hash"])
254		}
255	}
