257	func TestVerifyReadFailureAfterValidPrefixReturns503(t *testing.T) {
258		path := filepath.Join(t.TempDir(), "service.db")
259		st := openStoreAt(t, path)
260		defer closeStore(t, st)
261		router := NewRouter(st)
262		posted := seedEvents(t, router, 4)
263	
264		// Baseline: the intact chain verifies.
265		recorder := getLedgerVerifyRequest(t, router, "/ledger/verify")
266		if body := decodeVerify(t, recorder); !body.Valid || body.Checked != 4 || body.FirstInvalidSeq != nil {
267			t.Fatalf("baseline verify = %+v, want valid/4/null", body)
268		}
269	
270		// Records 1-2 are legal and read fine; the read fails at seq 3.
271		failReadsAt(t, path, 3)
272		assertFaultReadsPrefix(t, path, 1, 2)
273	
274		recorder = getLedgerVerifyRequest(t, router, "/ledger/verify")
275		wantStorageError(t, recorder, "valid", "checked", "first_invalid_seq")
276	
277		// Only the read path is broken: healthz still reports ok.
278		wantHealthy(t, router)
279	
280		// A query parameter is still a 400 before storage is touched, in the same
281		// error body shape.
282		wantInvalidAuditInput(t, getLedgerVerifyRequest(t, router, "/ledger/verify?detail=1"))
283	
284		// With the read path restored, the whole chain verifies again and the
285		// stored records are untouched.
286		restoreReads(t, path)
287		recorder = getLedgerVerifyRequest(t, router, "/ledger/verify")
288		if body := decodeVerify(t, recorder); !body.Valid || body.Checked != 4 || body.FirstInvalidSeq != nil {
289			t.Fatalf("restored verify = %+v, want valid/4/null", body)
290		}
291		assertVerifyExactFields(t, recorder)
292		page, next := decodePage(t, getEventsQuery(t, router, "limit=4"))
293		if next != nil {
294			t.Fatalf("next_after_seq = %v, want null on the only page", next)
295		}
296		wantEventsMatchPosted(t, page, posted)
297	
298		// Appends still chain onto the original tail.
299		fifth := mustPost(t, router, eventBody("audit", "2026-10-05T00:04:00Z"))
300		if fifth["seq"] != float64(5) || fifth["prev_hash"] != posted[3]["hash"] {
301			t.Fatalf("fifth = %v, want seq 5 chained to %s", fifth, posted[3]["hash"])
302		}
303	}
